@startuml

class InsurancePolicy {
  + PolicyId : int
  + Type : string
}

class Customer {
  + CustId : int
  + Name : string
}

class Contract {
  + ContractId : int
  + CustId : int
  + PolicyId : int
  + StartDate : datetime
  + EndDate : datetime
  + Premium : double
}

InsurancePolicy "1" -- "*" Customer
Customer "0..*" -- "*" Contract

@enduml

